/**
 * @file Типы доменной модели: строки БД и итоговый отчёт по профитным позициям.
 */

import type { DisplayCurrency } from '../lib/currency'
import type { BuyMarketId, MarketId } from '../lib/markets'

/**
 * Конфигурация приложения из `.env`.
 */
export interface AppConfig {
  spreadsheetId: string
  sheetTabBdSteam: string
  sheetTabBdBuff: string
  sheetTabBdLiskins: string
  sheetTabBdWhitemarket: string
  sheetTabBdMarketcsgo: string
  sheetTabBdCsfloat: string
  sheetTabBdSih: string
  /** Комиссия market.csgo при продаже (доля от 1, напр. 0.05 = 5%). */
  commission: number
}

/**
 * Одна потенциальная сделка «купить на A → продать на B» после расчёта маржи.
 */
export interface Opportunity {
  /** market_hash_name — ключ join между вкладками БД. */
  name: string
  /** Цена покупки на маркете-источнике в рублях. */
  buyRub: number
  /** Цена покупки на маркете-источнике в USD. */
  buyUsd: number
  /** Цена продажи на маркете-сравнения в RUB (до комиссии). */
  sellRub: number
  /** Цена продажи на маркете-сравнения в USD (до комиссии). */
  sellUsd: number
  /** Выручка после комиссии (если применима к маркету продажи). */
  netSellRub: number
  /** Выручка после комиссии в USD. */
  netSellUsd: number
  /**
   * Эффективный % комиссии Steam от цены покупателя (USD).
   * Заполняется при `sellMarket === 'steam'`. См. `STEAM-COMMISSION.md`.
   */
  netSellFeePctUsd?: number
  /**
   * Эффективный % комиссии Steam от цены покупателя (RUB).
   * Заполняется при `sellMarket === 'steam'`.
   */
  netSellFeePctRub?: number
  /** Абсолютная прибыль в рублях. */
  profitRub: number
  /** Абсолютная прибыль в USD. */
  profitUsd: number
  /** Относительная прибыль в % от вложения в покупку. */
  profitPct: number
  /** Продаж за 30 дней (если есть у market.csgo в паре). */
  sales30d: number
  /** Лотов в продаже на маркете продажи. */
  sellVolume: number
  /** Лотов в продаже на маркете покупки. */
  buyVolume: number
  /** Дата снимка цены покупки — колонка `time_msk`. */
  buyDate: string
  /** Дата снимка цены продажи — колонка `time_msk`. */
  sellDate: string
  /** Ссылка на лот на маркете покупки. */
  buyUrl: string
  /** Ссылка на лот на маркете продажи. */
  sellUrl: string
  /** Маркет покупки для этой позиции (режим «все источники»). */
  buyMarket?: BuyMarketId
  /** Цены покупки по всем источникам, ₽ (для тултипа). */
  buyMarketPrices?: Partial<Record<BuyMarketId, number>>
  /** Цены покупки по всем источникам, USD (для тултипа). */
  buyMarketPricesUsd?: Partial<Record<BuyMarketId, number>>
}

/** Суммы позиции в выбранной валюте отображения. */
export interface OpportunityAmounts {
  buy: number
  sell: number
  netSell: number
  profit: number
  /** % комиссии от цены покупателя (Steam / market.csgo), если применимо. */
  netSellFeePct?: number
}

/**
 * @param item — позиция после расчёта профита.
 * @param currency — валюта UI.
 */
export function getOpportunityAmounts(
  item: Opportunity,
  currency: DisplayCurrency,
): OpportunityAmounts {
  if (currency === 'USD') {
    return {
      buy: item.buyUsd,
      sell: item.sellUsd,
      netSell: item.netSellUsd,
      profit: item.profitUsd,
      netSellFeePct: item.netSellFeePctUsd,
    }
  }
  return {
    buy: item.buyRub,
    sell: item.sellRub,
    netSell: item.netSellRub,
    profit: item.profitRub,
    netSellFeePct: item.netSellFeePctRub,
  }
}

/**
 * Результат загрузки и расчёта: метаданные + отсортированный список сделок.
 */
export interface ProfitReport {
  /** Маркет покупки (источник); `null` — сравнение всех buy-маркетов. */
  buyMarket: MarketId | null
  /** Маркет продажи (сравнение). */
  sellMarket: MarketId
  /** Курс USD→RUB из мета-блока G:H вкладки маркета покупки. */
  buyUsdRub: number
  /** Курс USD→RUB из мета-блока G:H вкладки маркета продажи. */
  sellUsdRub: number
  /** Время формирования отчёта (МСК). */
  generatedAt: string
  /** Профитные позиции после фильтров, сортировка Profit % ↓. */
  items: Opportunity[]
}

/**
 * Строка вкладки `bd_steam` (колонки A–D).
 */
export interface SteamRow {
  name: string
  priceUsd: number
  sellListings: number
  /** Продаж за 30 дней (`bd_buff`, колонка D). */
  sales30d?: number
  /** Unix-секунды (из `time_msk`), для внутренней логики. */
  time: number
  /** Колонка `time_msk` как в БД: `DD-MM-YY HH:MM` (МСК). */
  timeMsk: string
}

/**
 * Строка вкладки `bd_marketcsgo` (колонки A–F).
 */
export interface MarketRow {
  name: string
  priceUsd: number
  priceRub: number
  sellListings: number
  sales30d: number
  time: number
  /** Колонка `time_msk` как в БД: `DD-MM-YY HH:MM` (МСК). */
  timeMsk: string
}

/**
 * Метаданные последнего прогона — блок G:H на вкладках БД.
 */
export interface SheetMeta {
  ts: number
  numberPositions: number
  usdRub: number
}

