/**
 * @file Точка монтирования React-приложения в DOM.
 */

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import App from './App'
import './index.css'

const rootEl = document.getElementById('root')
if (!rootEl) {
  throw new Error('Элемент #root не найден в index.html')
}

const mountTarget: HTMLElement = rootEl

/** Показывает fatal-ошибку старта, если React не смог смонтироваться. */
function showBootError(message: string): void {
  mountTarget.innerHTML = `
    <div style="font-family:system-ui,sans-serif;padding:24px;max-width:720px;color:#c5221f;background:#fce8e6;border:1px solid #f28b82;border-radius:8px;margin:24px auto;">
      <h2 style="margin:0 0 12px;color:#202124;">Ошибка запуска приложения</h2>
      <pre style="white-space:pre-wrap;margin:0;font-size:14px;color:#3c4043;">${message.replace(/</g, '&lt;')}</pre>
      <p style="margin:16px 0 0;color:#5f6368;font-size:14px;">Проверьте консоль браузера (F12) и перезапустите <code>npm run dev</code>.</p>
    </div>
  `
}

try {
  createRoot(mountTarget).render(
    <StrictMode>
      <App />
    </StrictMode>,
  )
} catch (err) {
  const message = err instanceof Error ? err.message : String(err)
  showBootError(message)
  console.error(err)
}
