/**
 * @file Валюта отображения и фильтров в UI.
 */

/** Валюта для цен, профита и фильтра «Покупаем на площадке». */
export type DisplayCurrency = 'USD' | 'RUB'

/** Валюта по умолчанию — данные в таблицах в основном в USD. */
export const DEFAULT_CURRENCY: DisplayCurrency = 'USD'

/**
 * @param currency — выбранная валюта.
 */
export function currencySymbol(currency: DisplayCurrency): string {
  return currency === 'USD' ? '$' : '₽'
}

/**
 * @param currency — выбранная валюта.
 */
export function currencyCode(currency: DisplayCurrency): string {
  return currency === 'USD' ? 'USD' : 'RUB'
}

/**
 * Переводит сумму фильтра между USD и RUB по курсу USD→RUB.
 *
 * @param value — сумма в текущей валюте.
 * @param from — исходная валюта.
 * @param to — целевая валюта.
 * @param usdRub — курс USD→RUB.
 */
export function convertAmount(
  value: number,
  from: DisplayCurrency,
  to: DisplayCurrency,
  usdRub: number,
): number {
  if (from === to || usdRub <= 0) return value
  return from === 'USD' ? value * usdRub : value / usdRub
}

/**
 * Конвертирует строку поля фильтра при смене валюты.
 *
 * @param raw — значение из input.
 * @param from — прежняя валюта.
 * @param to — новая валюта.
 * @param usdRub — курс USD→RUB.
 */
export function convertFilterInput(
  raw: string,
  from: DisplayCurrency,
  to: DisplayCurrency,
  usdRub: number,
): string {
  const trimmed = raw.trim()
  if (!trimmed || from === to || usdRub <= 0) return raw

  const n = Number(trimmed.replace(',', '.'))
  if (!Number.isFinite(n)) return raw

  const converted = convertAmount(n, from, to, usdRub)
  const rounded = to === 'USD'
    ? Math.round(converted * 100) / 100
    : Math.round(converted)

  return String(rounded)
}
