/**
 * @file Корневой React-комponent: выбор маркетов, загрузка Google Sheets и таблица.
 */

import { useCallback, useMemo, useState } from 'react'
import {
  filterOpportunities,
  parseFilterNumber,
  type OpportunityFilters,
} from './lib/filterOpportunities'
import { loadMultiBuyOpportunities, loadOpportunities } from './lib/loadOpportunities'
import {
  BUY_MARKET_OPTIONS,
  SALES_30D_SELL_MARKETS,
  SELL_MARKET_OPTIONS,
  type BuyMarketId,
  type MarketId,
} from './lib/markets'
import {
  convertFilterInput,
  currencySymbol,
  DEFAULT_CURRENCY,
  type DisplayCurrency,
} from './lib/currency'
import type { ProfitReport } from './types'
import { MultiSelect } from './components/MultiSelect'
import { ProfitableTable } from './components/ProfitableTable'
import './App.css'

/**
 * Главный экран приложения.
 *
 * Пользователь настраивает фильтры и нажимает «Искать» — тогда загружаются
 * вкладки Google Sheets и применяется фильтрация.
 */
function App() {
  const [currency, setCurrency] = useState<DisplayCurrency>(DEFAULT_CURRENCY)
  const [buyMarkets, setBuyMarkets] = useState<BuyMarketId[]>([])
  const [sellMarket, setSellMarket] = useState<MarketId | ''>('')
  const [report, setReport] = useState<ProfitReport | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [hasSearched, setHasSearched] = useState(false)
  const [activeBuyMarkets, setActiveBuyMarkets] = useState<BuyMarketId[]>([])
  const [activeSellMarket, setActiveSellMarket] = useState<MarketId | ''>('')
  const [appliedFilters, setAppliedFilters] = useState<OpportunityFilters | null>(
    null,
  )
  const [buyPriceFrom, setBuyPriceFrom] = useState('')
  const [buyPriceTo, setBuyPriceTo] = useState('')
  const [minBuyVolume, setMinBuyVolume] = useState('')
  const [minSales30d, setMinSales30d] = useState('')
  const [minSellVolume, setMinSellVolume] = useState('')
  const [minProfitPct, setMinProfitPct] = useState('')

  const marketsReady = Boolean(sellMarket && buyMarkets.length > 0)
  const multiBuyMode = buyMarkets.length > 1
  const sales30dFilterEnabled =
    sellMarket !== '' && SALES_30D_SELL_MARKETS.includes(sellMarket)

  const buyPriceFromNum = parseFilterNumber(buyPriceFrom)
  const buyPriceToNum = parseFilterNumber(buyPriceTo)
  const minBuyVolumeNum = parseFilterNumber(minBuyVolume)
  const minSales30dNum = parseFilterNumber(minSales30d)
  const minSellVolumeNum = parseFilterNumber(minSellVolume)
  const minProfitPctNum = parseFilterNumber(minProfitPct)

  const buyPriceRangeInvalid =
    buyPriceFromNum != null && buyPriceToNum != null && buyPriceFromNum > buyPriceToNum

  const appliedBuyPriceRangeInvalid =
    appliedFilters != null &&
    appliedFilters.buyFrom != null &&
    appliedFilters.buyTo != null &&
    appliedFilters.buyFrom > appliedFilters.buyTo

  const conversionRate = useMemo(() => {
    if (!report) return 0
    return report.buyUsdRub > 0 ? report.buyUsdRub : report.sellUsdRub
  }, [report])

  const filteredItems = useMemo(() => {
    if (!report || !appliedFilters || appliedBuyPriceRangeInvalid) return []
    return filterOpportunities(report.items, appliedFilters)
  }, [report, appliedFilters, appliedBuyPriceRangeInvalid])

  const handleBuyMarketsChange = (next: BuyMarketId[]) => {
    setBuyMarkets(next)
  }

  const handleSellMarketChange = (next: MarketId | '') => {
    if (next) {
      setBuyMarkets((prev) => prev.filter((m) => m !== next))
    }
    if (!next || !SALES_30D_SELL_MARKETS.includes(next)) {
      setMinSales30d('')
    }
    setSellMarket(next)
  }

  const handleCurrencyChange = (next: DisplayCurrency) => {
    if (next === currency) return

    if (conversionRate > 0) {
      setBuyPriceFrom((prev) => convertFilterInput(prev, currency, next, conversionRate))
      setBuyPriceTo((prev) => convertFilterInput(prev, currency, next, conversionRate))
      setAppliedFilters((prev) => {
        if (!prev) return prev
        return {
          ...prev,
          currency: next,
          buyFrom:
            prev.buyFrom != null
              ? Number(convertFilterInput(String(prev.buyFrom), currency, next, conversionRate))
              : null,
          buyTo:
            prev.buyTo != null
              ? Number(convertFilterInput(String(prev.buyTo), currency, next, conversionRate))
              : null,
        }
      })
    } else {
      setAppliedFilters((prev) => (prev ? { ...prev, currency: next } : prev))
    }

    setCurrency(next)
  }

  const buyMarketOptions = useMemo(
    () =>
      BUY_MARKET_OPTIONS.filter((m) => m.id !== sellMarket).map((m) => ({
        value: m.id as BuyMarketId,
        label: m.label,
      })),
    [sellMarket],
  )

  /** Загружает данные и применяет текущие значения фильтров. */
  const runSearch = useCallback(async () => {
    if (!sellMarket || buyMarkets.length === 0 || buyPriceRangeInvalid) {
      return
    }

    const filters: OpportunityFilters = {
      currency,
      buyFrom: buyPriceFromNum,
      buyTo: buyPriceToNum,
      minBuyVolume: minBuyVolumeNum,
      minSales30d: sales30dFilterEnabled ? minSales30dNum : null,
      minSellVolume: minSellVolumeNum,
      minProfitPct: minProfitPctNum,
    }

    setAppliedFilters(filters)
    setActiveBuyMarkets(buyMarkets)
    setActiveSellMarket(sellMarket)
    setHasSearched(true)
    setLoading(true)
    setError(null)

    const loadFilters = {
      buyPriceRange: {
        currency,
        from: buyPriceFromNum,
        to: buyPriceToNum,
      },
      minSales30d: sales30dFilterEnabled ? minSales30dNum : null,
    }

    try {
      const data =
        buyMarkets.length === 1
          ? await loadOpportunities(buyMarkets[0], sellMarket, loadFilters)
          : await loadMultiBuyOpportunities(sellMarket, buyMarkets, loadFilters)
      setReport(data)
    } catch (e) {
      setReport(null)
      setError(e instanceof Error ? e.message : String(e))
    } finally {
      setLoading(false)
    }
  }, [
    buyMarkets,
    sellMarket,
    buyPriceRangeInvalid,
    currency,
    buyPriceFromNum,
    buyPriceToNum,
    minBuyVolumeNum,
    minSales30dNum,
    minSellVolumeNum,
    minProfitPctNum,
    sales30dFilterEnabled,
  ])

  const buyLabel =
    activeBuyMarkets.length > 0
      ? activeBuyMarkets
          .map((id) => BUY_MARKET_OPTIONS.find((m) => m.id === id)?.label)
          .filter(Boolean)
          .join(', ')
      : null
  const sellLabel = activeSellMarket
    ? SELL_MARKET_OPTIONS.find((m) => m.id === activeSellMarket)?.label
    : null

  const activeMultiBuyMode = activeBuyMarkets.length > 1

  return (
    <div className="app">
      <header className="app-header">
        <div>
          <h1>Профитные скины</h1>
        </div>
        <button
          type="button"
          onClick={() => void runSearch()}
          disabled={loading || !marketsReady}
        >
          {loading ? 'Загрузка…' : 'Обновить'}
        </button>
      </header>

      <div className="app-body">
        <aside className="filters-panel">
          <label className="filter-block">
            <span className="filter-block-title">Валюта</span>
            <select
              className="filter-select"
              value={currency}
              onChange={(e) => handleCurrencyChange(e.target.value as DisplayCurrency)}
            >
              <option value="USD">USD ($)</option>
              <option value="RUB">RUB (₽)</option>
            </select>
          </label>

          <label className="filter-block">
            <span className="filter-block-title">Откуда берём</span>
            <MultiSelect
              options={buyMarketOptions}
              value={buyMarkets}
              onChange={handleBuyMarketsChange}
              placeholder="Выбрать"
              ariaLabel="Откуда берём"
              invalid={Boolean(sellMarket && buyMarkets.length === 0)}
            />
            {sellMarket && buyMarkets.length === 0 && (
              <span className="filter-hint">Выберите один или несколько маркетов</span>
            )}
          </label>

        <div className="filter-block">
          <span className="filter-block-title">
            Покупаем на площадке, {currencySymbol(currency)}
          </span>
          <div className="filter-range">
            <label className="filter-range-field">
              <span>От</span>
              <input
                type="number"
                min={0}
                step={currency === 'USD' ? 0.01 : 1}
                placeholder="—"
                value={buyPriceFrom}
                onChange={(e) => setBuyPriceFrom(e.target.value)}
                disabled={!sellMarket}
              />
            </label>
            <label className="filter-range-field">
              <span>До</span>
              <input
                type="number"
                min={0}
                step={currency === 'USD' ? 0.01 : 1}
                placeholder="—"
                value={buyPriceTo}
                onChange={(e) => setBuyPriceTo(e.target.value)}
                disabled={!sellMarket}
              />
            </label>
          </div>
          <label className="filter-range-field filter-range-field--solo">
            <span>В продаже, от</span>
            <input
              type="number"
              min={0}
              step={1}
              placeholder="—"
              value={minBuyVolume}
              onChange={(e) => setMinBuyVolume(e.target.value)}
              disabled={!sellMarket}
            />
          </label>
        </div>

        <label className="filter-block">
          <span className="filter-block-title">Продаем на площадке</span>
          <select
            className="filter-select"
            value={sellMarket}
            onChange={(e) => handleSellMarketChange(e.target.value as MarketId | '')}
          >
            <option value="">Выбрать</option>
            {SELL_MARKET_OPTIONS.map((m) => (
              <option key={m.id} value={m.id}>
                {m.label}
              </option>
            ))}
          </select>
        </label>

          <div className="filter-block">
              <label className="filter-range-field">
                <span>Продаж/мес, от</span>
                <input
                    type="number"
                    min={0}
                    step={1}
                    placeholder="—"
                    value={minSales30d}
                    onChange={(e) => setMinSales30d(e.target.value)}
                    disabled={!sales30dFilterEnabled}
                />
              </label>
            <label className="filter-range-field">
              <span>В продаже, от</span>
              <input
                  type="number"
                  min={0}
                  step={1}
                  placeholder="—"
                  value={minSellVolume}
                  onChange={(e) => setMinSellVolume(e.target.value)}
                  disabled={!sellMarket}
              />
            </label>
            <label className="filter-range-field filter-range-field--solo">
              <span>Profit %, от</span>
              <input
                  type="number"
                  step={0.1}
                  placeholder="—"
                  value={minProfitPct}
                  onChange={(e) => setMinProfitPct(e.target.value)}
                  disabled={!sellMarket}
              />
            </label>
          </div>

          <button
              type="button"
              className="filters-search-btn"
              onClick={() => void runSearch()}
              disabled={loading || !marketsReady || buyPriceRangeInvalid}
          >
            {loading ? 'Загрузка…' : 'Искать'}
          </button>
        </aside>

        <div className="main-column">
          <section className="meta-bar" aria-label="Сводка по данным">
            {!hasSearched && (
              <span className="meta-bar-muted">
                {!marketsReady
                  ? 'Выберите маркеты и нажмите «Искать».'
                  : 'Нажмите «Искать» для загрузки данных.'}
              </span>
            )}

            {hasSearched && loading && (
              <span className="meta-bar-muted">Загрузка данных из Google Sheets…</span>
            )}

            {hasSearched && !loading && error && (
              <span className="meta-bar-muted">Ошибка загрузки — см. сообщение ниже.</span>
            )}

            {report && hasSearched && !loading && (
              <>
                <span>
                  Маркеты: {buyLabel} → {sellLabel}
                </span>
                <span>
                  Курс {activeMultiBuyMode ? 'источников' : buyLabel}:{' '}
                  {report.buyUsdRub > 0
                    ? report.buyUsdRub.toFixed(2)
                    : activeMultiBuyMode
                      ? 'по маркету'
                      : '—'}
                </span>
                <span>
                  Курс {sellLabel}:{' '}
                  {report.sellUsdRub > 0 ? report.sellUsdRub.toFixed(2) : '—'}
                </span>
                <span>Обновлено: {report.generatedAt}</span>
                <span>Показано позиций: {filteredItems.length}</span>
              </>
            )}
          </section>

          {buyPriceRangeInvalid && (
            <div className="error-banner">«От» не может быть больше «До».</div>
          )}

          {error && <div className="error-banner">{error}</div>}

          <ProfitableTable
            data={
              !hasSearched || appliedBuyPriceRangeInvalid || !report ? [] : filteredItems
            }
            buyMarkets={hasSearched ? activeBuyMarkets : buyMarkets}
            sellMarket={hasSearched ? activeSellMarket : sellMarket}
            multiBuyMode={hasSearched ? activeMultiBuyMode : multiBuyMode}
            currency={currency}
            loading={loading}
            searched={hasSearched}
            loadError={error}
          />
        </div>
      </div>
    </div>
  )
}

export default App
