/**
 * @file Расчёт комиссии Steam Community Market (CS2).
 *
 * Реализация алгоритма `GetItemPriceFromTotal` / `ToValidMarketPrice` из клиента Steam
 * (см. {@link https://github.com/LinarSharifullin/steamcom/blob/master/steamcom/fee_counter.py steamcom/fee_counter.py}
 * и документ `STEAM-COMMISSION.md` в корне проекта).
 *
 * **Важно:** проценты 5% и 10% берутся от суммы «Вы получите», а не от цены покупателя.
 * На дешёвых лотах действует `marketMinimum` — эффективный % выше ~13%.
 */

/** Валюта кошелька Steam для выбора параметров комиссии. */
export type SteamWalletCurrency = 'USD' | 'RUB'

/**
 * Параметры кошелька Steam (`g_rgWalletInfo`), влияющие на расчёт.
 *
 * @see STEAM-COMMISSION.md — откуда брать значения
 */
export interface SteamFeeConfig {
  /**
   * `wallet_market_minimum` — минимальная величина одной комиссии
   * в **минорных единицах** (центы USD / копейки RUB).
   * USD: 1 ($0.01). RUB: {@link rubMarketMinimumFromUsdRub} от курса таблицы.
   */
  marketMinimum: number
  /** `wallet_fee_percent` — комиссия Steam (0.05 = 5%). */
  steamFeePercent: number
  /** `wallet_publisher_fee_percent_default` — комиссия издателя CS2 (0.10 = 10%). */
  publisherFeePercent: number
  /** `wallet_currency_increment` — шаг цены на маркете (обычно 1). */
  currencyIncrement: number
}

/** Результат расчёта: выручка продавца и разбивка комиссии. */
export interface SteamNetSellResult {
  /** Сумма «Вы получите» в тех же единицах, что `buyerPrice`. */
  sellerReceive: number
  /** Комиссия Steam (5% или minimum). */
  steamFee: number
  /** Комиссия CS2 (10% или minimum). */
  publisherFee: number
  /** Суммарная комиссия. */
  totalFee: number
  /**
   * Эффективный процент комиссии **от цены покупателя**
   * (`totalFee / buyerPrice × 100`). Не равен 15% на малых суммах.
   */
  feePctFromBuyer: number
}

/** Дефолты по валюте (эталон steamcom / g_rgWalletInfo). */
export const STEAM_FEE_DEFAULTS: Record<SteamWalletCurrency, SteamFeeConfig> = {
  USD: {
    marketMinimum: 1,
    steamFeePercent: 0.05,
    publisherFeePercent: 0.10,
    currencyIncrement: 1,
  },
  RUB: {
    /** Fallback, если курс не передан; в приложении берётся из `usdRub` таблицы. */
    marketMinimum: 79,
    steamFeePercent: 0.05,
    publisherFeePercent: 0.10,
    currencyIncrement: 1,
  },
}

/**
 * Минимальная комиссия Steam в **копейках** для RUB-кошелька,
 * эквивалентная **$0.01** (1 цент USD) по курсу из мета-блока G:H таблицы.
 *
 * Steam задаёт `wallet_market_minimum` в минорных единицах валюты кошелька;
 * для RUB это ≈ 1 цент USD × `usdRub` (₽/$1).
 *
 * ```
 * 0.01 USD × usdRub ₽/USD = usdRub коп.   (т.к. 0.01 ₽ = 1 коп.)
 * marketMinimum = floor(usdRub)
 * ```
 *
 * @param usdRub — курс USD→RUB из `SheetMeta.usdRub` (вкладка sell-side, напр. `bd_steam`).
 * @returns Минимум в копейках, не меньше 1.
 *
 * @example
 * rubMarketMinimumFromUsdRub(78.28) // → 78 коп. (0,78 ₽)
 * rubMarketMinimumFromUsdRub(100)    // → 100 коп. (1,00 ₽)
 */
export function rubMarketMinimumFromUsdRub(usdRub: number): number {
  if (!Number.isFinite(usdRub) || usdRub <= 0) {
    return STEAM_FEE_DEFAULTS.RUB.marketMinimum
  }
  return Math.max(1, Math.floor(usdRub + 1e-9))
}

/**
 * Конфиг комиссии Steam для RUB с `marketMinimum` от курса таблицы.
 *
 * @param usdRub — курс USD→RUB (`SheetMeta.usdRub`).
 */
export function steamRubFeeConfig(usdRub: number): SteamFeeConfig {
  return {
    ...STEAM_FEE_DEFAULTS.RUB,
    marketMinimum: rubMarketMinimumFromUsdRub(usdRub),
  }
}

/**
 * Переводит цену в минорные единицы (центы / копейки) с округлением вниз.
 * Steam использует `Math.floor(price * 100 + 1e-6)`; минимум лота — 0.03.
 *
 * @param major — цена в долларах или рублях.
 */
export function toMinorUnits(major: number): number {
  if (!major || major <= 0) return 0
  const clamped = major < 0.03 ? 0.03 : major
  return Math.max(Math.floor(clamped * 100 + 1e-6), 0)
}

/**
 * `ToValidMarketPrice` из economy.js: если значение ≤ minimum — подставляется minimum.
 *
 * @param minor — сумма в центах/копейках.
 * @param config — параметры кошелька.
 */
export function toValidMarketPrice(minor: number, config: SteamFeeConfig): number {
  if (minor <= config.marketMinimum) return config.marketMinimum
  if (minor <= config.currencyIncrement) return config.currencyIncrement
  if (config.currencyIncrement > 1) {
    const amount = minor / config.currencyIncrement
    const sign = amount < 0 ? -1 : 1
    return sign * Math.floor(Math.abs(amount) + 0.5) * config.currencyIncrement
  }
  return minor
}

/**
 * Одна часть комиссии: `ToValidMarketPrice(floor(base × percent))`.
 *
 * @param baseMinor — база «Вы получите» в минорных единицах.
 * @param percent — 0.05 или 0.10.
 * @param config — параметры кошелька.
 */
export function calculateSteamFeePart(
  baseMinor: number,
  percent: number,
  config: SteamFeeConfig,
): number {
  if (percent <= 0) return 0
  return toValidMarketPrice(Math.floor(baseMinor * percent), config)
}

/**
 * Прямой расчёт: из суммы продавца → цена покупателя (`GetTotalWithFees`).
 *
 * @param sellerMinor — «Вы получите» в центах/копейках.
 * @param config — параметры кошелька.
 * @returns Цена покупателя в минорных единицах.
 */
export function buyerFromSellerMinor(sellerMinor: number, config: SteamFeeConfig): number {
  const base = toValidMarketPrice(sellerMinor, config)
  const pub = calculateSteamFeePart(sellerMinor, config.publisherFeePercent, config)
  const steam = calculateSteamFeePart(sellerMinor, config.steamFeePercent, config)
  return base + pub + steam
}

/**
 * Обратный расчёт: цена покупателя на маркете → «Вы получите» (`GetItemPriceFromTotal`).
 *
 * Цена в листинге Steam (`bd_steam.price_usd` / конвертированный RUB) — это **покупатель платит**.
 * Перебор `base ± increment` до совпадения с `buyerMinor`.
 *
 * @param buyerMinor — цена покупателя в центах/копейках.
 * @param config — параметры кошелька.
 * @returns Сумма продавца в минорных единицах.
 */
export function sellerFromBuyerMinor(buyerMinor: number, config: SteamFeeConfig): number {
  if (buyerMinor <= 0) return 0

  const initialGuess = Math.floor(
    buyerMinor / (1 + config.publisherFeePercent + config.steamFeePercent),
  )
  const maxBase = buyerMinor - 2 * config.marketMinimum
  let base = toValidMarketPrice(Math.min(initialGuess, maxBase), config)
  let higher = false

  for (let i = 0; i < 50; i++) {
    const calculated = buyerFromSellerMinor(base, config)
    if (calculated === buyerMinor) return base
    if (calculated < buyerMinor) {
      if (higher) break
      base += config.currencyIncrement
    } else {
      if (base <= config.marketMinimum) break
      base -= config.currencyIncrement
      higher = true
    }
  }

  return Math.max(config.marketMinimum, base)
}

/**
 * Чистая выручка после комиссии Steam по **цене покупателя** (листинг на маркете).
 *
 * @param buyerPrice — цена на маркете (Steam USD или RUB после конвертации).
 * @param walletCurrency — `'USD'` для `price_usd`, `'RUB'` для рублёвой цены лота.
 * @param configOverride — переопределение `g_rgWalletInfo`.
 * @param usdRub — курс USD→RUB из таблицы; для `walletCurrency === 'RUB'` задаёт
 *   `marketMinimum` через {@link rubMarketMinimumFromUsdRub} (1 цент USD по курсу).
 */
export function steamNetSellFromBuyerPrice(
  buyerPrice: number,
  walletCurrency: SteamWalletCurrency,
  configOverride?: Partial<SteamFeeConfig>,
  usdRub?: number,
): SteamNetSellResult {
  const baseConfig =
    walletCurrency === 'RUB' && usdRub != null && usdRub > 0
      ? steamRubFeeConfig(usdRub)
      : STEAM_FEE_DEFAULTS[walletCurrency]

  const config: SteamFeeConfig = {
    ...baseConfig,
    ...configOverride,
  }

  const buyerMinor = toMinorUnits(buyerPrice)
  if (buyerMinor <= 0) {
    return {
      sellerReceive: 0,
      steamFee: 0,
      publisherFee: 0,
      totalFee: 0,
      feePctFromBuyer: 0,
    }
  }

  const sellerMinor = sellerFromBuyerMinor(buyerMinor, config)
  const steamFeeMinor = calculateSteamFeePart(sellerMinor, config.steamFeePercent, config)
  const publisherFeeMinor = calculateSteamFeePart(
    sellerMinor,
    config.publisherFeePercent,
    config,
  )
  const totalFeeMinor = steamFeeMinor + publisherFeeMinor

  const div = 100
  return {
    sellerReceive: sellerMinor / div,
    steamFee: steamFeeMinor / div,
    publisherFee: publisherFeeMinor / div,
    totalFee: totalFeeMinor / div,
    feePctFromBuyer: buyerMinor > 0 ? (totalFeeMinor / buyerMinor) * 100 : 0,
  }
}
