/**
 * @file Клиентские фильтры таблицы.
 *
 * Цена покупки и min sales 30d отсекаются на Google при загрузке (gviz `tq`);
 * здесь остаются profit % и объёмы листингов.
 */

import type { DisplayCurrency } from './currency'
import type { Opportunity } from '../types'
import { getOpportunityAmounts } from '../types'

/**
 * Парсит число из поля ввода (рубли, штуки, проценты).
 *
 * @param raw — строка из поля ввода.
 * @returns Число или `null`, если поле пустое / некорректное.
 */
export function parseFilterNumber(raw: string): number | null {
  const trimmed = raw.trim()
  if (!trimmed) return null
  const n = Number(trimmed.replace(',', '.'))
  return Number.isFinite(n) ? n : null
}

/** Параметры фильтрации загруженных позиций. */
export interface OpportunityFilters {
  currency: DisplayCurrency
  buyFrom: number | null
  buyTo: number | null
  minBuyVolume: number | null
  minSales30d: number | null
  minSellVolume: number | null
  minProfitPct: number | null
}

/**
 * Применяет фильтры из панели слева.
 *
 * @param items — все позиции пересечения маркетов.
 * @param filters — активные границы фильтров.
 */
export function filterOpportunities(
  items: Opportunity[],
  filters: OpportunityFilters,
): Opportunity[] {
  const {
    currency,
    buyFrom,
    buyTo,
    minBuyVolume,
    minSales30d,
    minSellVolume,
    minProfitPct,
  } = filters

  return items.filter((item) => {
    const amounts = getOpportunityAmounts(item, currency)
    if (buyFrom != null && amounts.buy < buyFrom) return false
    if (buyTo != null && amounts.buy > buyTo) return false
    if (minBuyVolume != null && item.buyVolume < minBuyVolume) return false
    if (minSales30d != null && item.sales30d < minSales30d) return false
    if (minSellVolume != null && item.sellVolume < minSellVolume) return false
    if (minProfitPct != null && item.profitPct < minProfitPct) return false
    return true
  })
}
