/**
 * @file Расчёт позиций для произвольной пары маркетов.
 *
 * Join по `market_hash_name` + расчёт маржи. Фильтрация — только в UI.
 * Комиссия market.csgo применяется только при продаже на Market.CSGO.
 * Комиссия Steam — алгоритм `steamFees.ts` (см. STEAM-COMMISSION.md).
 */

import { appConfig } from '../config'
import { steamNetSellFromBuyerPrice } from './steamFees'
import type {
  MarketRow,
  Opportunity,
  ProfitReport,
  SheetMeta,
  SteamRow,
} from '../types'
import {
  buffListingUrl,
  csfloatListingUrl,
  liskinsListingUrl,
  sihListingUrl,
  SALES_30D_SELL_MARKETS,
  type BuyMarketId,
  type MarketId,
  whiteMarketListingUrl,
} from './markets'
import { fmtTsBd } from './sheets'

/**
 * Округляет число до заданного числа знаков.
 *
 * @param x — исходное значение.
 * @param places — количество знаков после запятой.
 */
function round(x: number, places: number): number {
  const m = 10 ** places
  return Math.round(x * m) / m
}

/**
 * URL лота в Steam Community Market.
 *
 * @param name — market_hash_name.
 */
export function steamListingUrl(name: string): string {
  return `https://steamcommunity.com/market/listings/730/${encodeURIComponent(name)}`
}

/**
 * URL поиска лота на market.csgo (рублёвая локаль).
 *
 * @param name — market_hash_name.
 */
export function marketCsgoUrl(name: string): string {
  return `https://market.csgo.com/ru/?search=${encodeURIComponent(name)}`
}

/** Нормализованная строка БД для join и расчёта. */
interface NormalizedRow {
  name: string
  priceUsd: number
  priceRub: number | null
  sellListings: number
  sales30d: number
  timeMsk: string
}

/**
 * @param market — id маркета.
 * @param name — market_hash_name.
 */
function listingUrl(market: MarketId, name: string): string {
  switch (market) {
    case 'steam':
      return steamListingUrl(name)
    case 'buff':
      return buffListingUrl(name)
    case 'liskins':
      return liskinsListingUrl(name)
    case 'whitemarket':
      return whiteMarketListingUrl(name)
    case 'csfloat':
      return csfloatListingUrl(name)
    case 'sih':
      return sihListingUrl(name)
    case 'marketcsgo':
      return marketCsgoUrl(name)
  }
}

/**
 * @param row — строка Steam/Buff (A–D).
 */
function normalizeBuySide(row: SteamRow): NormalizedRow {
  return {
    name: row.name,
    priceUsd: row.priceUsd,
    priceRub: null,
    sellListings: row.sellListings,
    sales30d: row.sales30d ?? 0,
    timeMsk: row.timeMsk,
  }
}

/**
 * @param row — строка market.csgo (A–F).
 */
function normalizeMarketcsgo(row: MarketRow): NormalizedRow {
  return {
    name: row.name,
    priceUsd: row.priceUsd,
    priceRub: row.priceRub,
    sellListings: row.sellListings,
    sales30d: row.sales30d,
    timeMsk: row.timeMsk,
  }
}

/**
 * Цена покупки в рублях и USD для строки маркета-источника.
 *
 * @param row — нормализованная строка покупки.
 * @param market — маркет покупки.
 * @param usdRub — курс USD→RUB.
 */
function buyPrices(
  row: NormalizedRow,
  market: MarketId,
  usdRub: number,
): { buyUsd: number; buyRub: number } {
  if (market === 'marketcsgo' && row.priceRub != null) {
    const buyRub = row.priceRub
    const buyUsd = row.priceUsd > 0 ? row.priceUsd : usdRub > 0 ? buyRub / usdRub : 0
    return { buyUsd, buyRub }
  }
  const buyUsd = row.priceUsd
  return { buyUsd, buyRub: buyUsd * usdRub }
}

/**
 * Валовая и чистая выручка при продаже на выбранном маркете.
 *
 * Для Steam цена лота (`price_usd` / `sellRub`) — **покупатель платит**;
 * чистая выручка — через {@link steamNetSellFromBuyerPrice} (USD/RUB отдельно).
 *
 * @param row — нормализованная строка продажи.
 * @param market — маркет продажи.
 * @param usdRub — курс USD→RUB.
 */
function sellPrices(
  row: NormalizedRow,
  market: MarketId,
  usdRub: number,
): {
  sellRub: number
  sellUsd: number
  netSellRub: number
  netSellUsd: number
  netSellFeePctUsd?: number
  netSellFeePctRub?: number
} {
  if (market === 'marketcsgo' && row.priceRub != null) {
    const sellRub = row.priceRub
    const sellUsd = row.priceUsd
    const feePct = appConfig.commission * 100
    return {
      sellRub,
      sellUsd,
      netSellRub: sellRub * (1 - appConfig.commission),
      netSellUsd: sellUsd * (1 - appConfig.commission),
      netSellFeePctUsd: feePct,
      netSellFeePctRub: feePct,
    }
  }
  if (market === 'steam') {
    const sellUsd = row.priceUsd
    const sellRub = sellUsd * usdRub
    const netUsd = steamNetSellFromBuyerPrice(sellUsd, 'USD')
    const netRub = steamNetSellFromBuyerPrice(sellRub, 'RUB', undefined, usdRub)
    return {
      sellRub,
      sellUsd,
      netSellRub: netRub.sellerReceive,
      netSellUsd: netUsd.sellerReceive,
      netSellFeePctUsd: netUsd.feePctFromBuyer,
      netSellFeePctRub: netRub.feePctFromBuyer,
    }
  }
  const sellUsd = row.priceUsd
  const sellRub = sellUsd * usdRub
  return { sellRub, sellUsd, netSellRub: sellRub, netSellUsd: sellUsd }
}

/**
 * Находит пересечение двух маркетов и считает маржу по каждой общей позиции.
 *
 * @param buyRows — строки маркета покупки.
 * @param sellRows — строки маркета продажи.
 * @param buyMeta — мета G:H вкладки покупки.
 * @param sellMeta — мета G:H вкладки продажи.
 * @param buyMarket — откуда покупаем.
 * @param sellMarket — куда продаём / с чем сравниваем.
 */
export function computeProfit(
  buyRows: SteamRow[] | MarketRow[],
  sellRows: SteamRow[] | MarketRow[],
  buyMeta: SheetMeta,
  sellMeta: SheetMeta,
  buyMarket: MarketId,
  sellMarket: MarketId,
): ProfitReport {
  const buyUsdRub = buyMeta.usdRub
  const sellUsdRub = sellMeta.usdRub

  const normalizedBuy = buyRows.map((r) =>
    buyMarket === 'marketcsgo'
      ? normalizeMarketcsgo(r as MarketRow)
      : normalizeBuySide(r as SteamRow),
  )
  const sellByName = new Map(
    sellRows.map((r) => [
      r.name,
      sellMarket === 'marketcsgo'
        ? normalizeMarketcsgo(r as MarketRow)
        : normalizeBuySide(r as SteamRow),
    ]),
  )

  const items: Opportunity[] = []

  for (const buy of normalizedBuy) {
    const sell = sellByName.get(buy.name)
    if (!sell) continue

    const { buyUsd, buyRub } = buyPrices(buy, buyMarket, buyUsdRub)
    const {
      sellRub,
      sellUsd,
      netSellRub,
      netSellUsd,
      netSellFeePctUsd,
      netSellFeePctRub,
    } = sellPrices(sell, sellMarket, sellUsdRub)
    const profitRub = netSellRub - buyRub
    const profitUsd = netSellUsd - buyUsd
    const profitPct = buyRub > 0 ? (profitRub / buyRub) * 100 : 0

    const sales30d = SALES_30D_SELL_MARKETS.includes(sellMarket)
      ? sell.sales30d
      : buyMarket === 'marketcsgo'
        ? buy.sales30d
        : 0

    items.push({
      name: buy.name,
      buyRub: round(buyRub, 2),
      buyUsd: round(buyUsd, 2),
      sellRub: round(sellRub, 2),
      sellUsd: round(sellUsd, 2),
      netSellRub: round(netSellRub, 2),
      netSellUsd: round(netSellUsd, 2),
      netSellFeePctUsd:
        netSellFeePctUsd != null ? round(netSellFeePctUsd, 1) : undefined,
      netSellFeePctRub:
        netSellFeePctRub != null ? round(netSellFeePctRub, 1) : undefined,
      profitRub: round(profitRub, 2),
      profitUsd: round(profitUsd, 2),
      profitPct: round(profitPct, 1),
      sales30d,
      sellVolume: sell.sellListings,
      buyVolume: buy.sellListings,
      buyDate: buy.timeMsk,
      sellDate: sell.timeMsk,
      buyUrl: listingUrl(buyMarket, buy.name),
      sellUrl: listingUrl(sellMarket, buy.name),
      buyMarket: buyMarket as BuyMarketId,
    })
  }

  items.sort((a, b) => b.profitPct - a.profitPct)

  return {
    buyMarket,
    sellMarket,
    buyUsdRub: round(buyUsdRub, 2),
    sellUsdRub: round(sellUsdRub, 2),
    generatedAt: fmtTsBd(Math.floor(Date.now() / 1000)),
    items,
  }
}

function isBetterOpportunity(a: Opportunity, b: Opportunity): boolean {
  if (a.profitPct !== b.profitPct) return a.profitPct > b.profitPct
  if (a.profitRub !== b.profitRub) return a.profitRub > b.profitRub
  return a.buyRub < b.buyRub
}

/**
 * Сравнивает все buy-маркеты с одним sell-маркетом и оставляет лучший источник на позицию.
 *
 * @param buyByMarket — загруженные данные каждого маркета покупки.
 * @param sellRows — строки маркета продажи.
 * @param sellMeta — мета G:H вкладки продажи.
 * @param sellMarket — куда продаём / с чем сравниваем.
 */
export function computeMultiBuyProfit(
  buyByMarket: Record<
    BuyMarketId,
    { rows: SteamRow[] | MarketRow[]; meta: SheetMeta }
  >,
  buyMarkets: BuyMarketId[],
  sellRows: SteamRow[] | MarketRow[],
  sellMeta: SheetMeta,
  sellMarket: MarketId,
): ProfitReport {
  const merged = new Map<string, Opportunity>()
  const pricesByName = new Map<string, Partial<Record<BuyMarketId, number>>>()
  const pricesUsdByName = new Map<string, Partial<Record<BuyMarketId, number>>>()

  for (const buyMarket of buyMarkets) {
    const { rows, meta } = buyByMarket[buyMarket]
    const report = computeProfit(rows, sellRows, meta, sellMeta, buyMarket, sellMarket)

    for (const item of report.items) {
      const prices = pricesByName.get(item.name) ?? {}
      prices[buyMarket] = item.buyRub
      pricesByName.set(item.name, prices)

      const pricesUsd = pricesUsdByName.get(item.name) ?? {}
      pricesUsd[buyMarket] = item.buyUsd
      pricesUsdByName.set(item.name, pricesUsd)

      const existing = merged.get(item.name)
      const candidate: Opportunity = { ...item, buyMarket }
      if (!existing || isBetterOpportunity(candidate, existing)) {
        merged.set(item.name, candidate)
      }
    }
  }

  const items = Array.from(merged.values()).map((item) => ({
    ...item,
    buyMarketPrices: pricesByName.get(item.name),
    buyMarketPricesUsd: pricesUsdByName.get(item.name),
  }))

  items.sort((a, b) => b.profitPct - a.profitPct)

  return {
    buyMarket: null,
    sellMarket,
    buyUsdRub: 0,
    sellUsdRub: round(sellMeta.usdRub, 2),
    generatedAt: fmtTsBd(Math.floor(Date.now() / 1000)),
    items,
  }
}
