/**
 * @file Конфигурация приложения.
 *
 * Значения генерируются в {@link ./generated/appConfig.ts} из `.env` при старте Rspack.
 * Схема вкладок совпадает с `profitable_skins` / `parser_skins`.
 * Фильтры позиций — только в UI (`App.tsx`).
 */

export { appConfig } from './generated/appConfig'
import { appConfig } from './generated/appConfig'

/**
 * Проверяет, что заданы обязательные параметры перед обращением к Google Sheets.
 *
 * @throws {Error} Если `SPREADSHEET_ID` пустой.
 */
export function assertAppConfig(): void {
  if (!appConfig.spreadsheetId) {
    throw new Error(
      'SPREADSHEET_ID не задан. Укажите ID публичной таблицы в .env и перезапустите dev/build.',
    )
  }
}
