/** Идентификатор маркета, для которого есть вкладка БД в Google Sheets. */
export type MarketId =
  | 'steam'
  | 'buff'
  | 'liskins'
  | 'whitemarket'
  | 'marketcsgo'
  | 'csfloat'
  | 'sih'

