/** Маркеты для селекта «Продаем на площадке». */
export const SELL_MARKET_OPTIONS: MarketInfo[] = [
  { id: 'marketcsgo', label: 'Market.CSGO', shortLabel: 'Market' },
  { id: 'buff', label: 'Buff', shortLabel: 'Buff' },
  { id: 'steam', label: 'Steam', shortLabel: 'Steam' },
]

/** Маркеты продажи с колонкой `sales_30d` в БД. */
export const SALES_30D_SELL_MARKETS: MarketId[] = ['marketcsgo', 'buff']

/** Все маркеты (для заголовков таблицы и расчёта). */
export const MARKET_OPTIONS: MarketInfo[] = Array.from(
  new Map(
    [...BUY_MARKET_OPTIONS, ...SELL_MARKET_OPTIONS].map((m) => [m.id, m]),
  ).values(),
)

/** Карта маркетов по id. */
export const MARKETS: Record<MarketId, MarketInfo> = Object.fromEntries(
  MARKET_OPTIONS.map((m) => [m.id, m]),
) as Record<MarketId, MarketInfo>

/**
 * URL лота на Buff163 (поиск по market_hash_name).
 *
 * @param name — market_hash_name.
 */
export function buffListingUrl(name: string): string {
  return `https://buff.163.com/market/csgo#tab=selling&search=${encodeURIComponent(name)}`
}

/**
 * Slug для страницы лота на LIS-SKINS из `market_hash_name`.
 *
 * Пример: `AK-47 | Wild Lotus (Factory New)` → `ak-47-wild-lotus-factory-new`.
 *
 * @param name — market_hash_name.
 */
export function liskinsSlug(name: string): string {
  return name
    .toLowerCase()
    .replace(/™/g, '')
    .replace(/\s*\|\s*/g, '-')
    .replace(/[()]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
}

/**
 * URL страницы лота на LIS-SKINS.
 *
 * @param name — market_hash_name.
 */
export function liskinsListingUrl(name: string): string {
  const slug = liskinsSlug(name)
  return `https://lis-skins.com/ru/market/csgo/${encodeURIComponent(slug)}/`
}

/**
 * URL страницы лота на white.market.
 *
 * @param name — market_hash_name.
 */
export function whiteMarketListingUrl(name: string): string {
  return `https://white.market/item?appId=730&nameHash=${encodeURIComponent(name)}`
}

/**
 * URL поиска лота на CSFLOAT.
 *
 * @param name — market_hash_name.
 */
export function csfloatListingUrl(name: string): string {
  const params = new URLSearchParams({
    sort_by: 'lowest_price',
    type: 'buy_now',
    market_hash_name: name,
  })
  return `https://csfloat.com/search?${params}`
}

/**
 * URL поиска лота на SIH Market.
 *
 * @param name — market_hash_name.
 */
export function sihListingUrl(name: string): string {
  return `https://sih.app/market?search=${encodeURIComponent(name)}`
}
