/**
 * @file Выпадающий список с множественным выбором (стиль как у `.filter-select`).
 */

import { useEffect, useId, useRef, useState } from 'react'

export interface MultiSelectOption<T extends string = string> {
  value: T
  label: string
}

interface MultiSelectProps<T extends string> {
  options: MultiSelectOption<T>[]
  value: T[]
  onChange: (value: T[]) => void
  placeholder?: string
  ariaLabel?: string
  invalid?: boolean
}

/**
 * Селект с чекбоксами в выпадающей панели.
 */
export function MultiSelect<T extends string>({
  options,
  value,
  onChange,
  placeholder = 'Выбрать',
  ariaLabel,
  invalid = false,
}: MultiSelectProps<T>) {
  const listboxId = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const [open, setOpen] = useState(false)

  const selectedLabels = options
    .filter((opt) => value.includes(opt.value))
    .map((opt) => opt.label)

  const triggerLabel =
    selectedLabels.length === 0
      ? placeholder
      : selectedLabels.length <= 2
        ? selectedLabels.join(', ')
        : `${selectedLabels.length} выбрано`

  useEffect(() => {
    if (!open) return

    const handlePointerDown = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false)
      }
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }

    document.addEventListener('mousedown', handlePointerDown)
    document.addEventListener('keydown', handleKeyDown)
    return () => {
      document.removeEventListener('mousedown', handlePointerDown)
      document.removeEventListener('keydown', handleKeyDown)
    }
  }, [open])

  const toggleOption = (optionValue: T) => {
    if (value.includes(optionValue)) {
      onChange(value.filter((item) => item !== optionValue))
      return
    }
    onChange([...value, optionValue])
  }

  return (
    <div
      ref={rootRef}
      className={`multi-select${open ? ' multi-select--open' : ''}${invalid ? ' multi-select--invalid' : ''}`}
    >
      <button
        type="button"
        className="multi-select-trigger filter-select"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listboxId}
        aria-label={ariaLabel}
        onClick={() => setOpen((prev) => !prev)}
      >
        <span
          className={`multi-select-trigger-label${selectedLabels.length === 0 ? ' multi-select-trigger-label--placeholder' : ''}`}
        >
          {triggerLabel}
        </span>
        <span className="multi-select-chevron" aria-hidden="true" />
      </button>

      {open && (
        <ul id={listboxId} className="multi-select-menu" role="listbox" aria-multiselectable="true">
          {options.map((opt) => {
            const checked = value.includes(opt.value)
            return (
              <li key={opt.value} role="presentation">
                <label className="multi-select-option">
                  <input
                    type="checkbox"
                    checked={checked}
                    onChange={() => toggleOption(opt.value)}
                  />
                  <span>{opt.label}</span>
                </label>
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}
