/**
 * Загружает вкладку `bd_marketcsgo`: позиции A2:F и мета G1:H10.
 *
 * @param options — buy: `buyPriceRange` (C, ₽); sell: `minSales30d` (E).
 */
export async function loadBdMarketcsgo(
  options?: MarketcsgoLoadOptions | null,
): Promise<{
  rows: MarketRow[]
  meta: SheetMeta
}> {
  const tab = appConfig.sheetTabBdMarketcsgo
  const metaRows = await readRangeWithRetry(tab, 'G1:H10')
  const meta = parseMeta(metaRows)

  const itemRows = await readMarketcsgoItems(tab, options)

  const rows: MarketRow[] = []
  for (const r of itemRows) {
    if (r.length < 5) continue
    const name = r[0]
    const priceUsd = Number(r[1].replace(',', '.'))
    const priceRub = Number(r[2].replace(',', '.'))
    const sellListings = Number(r[3]) || 0
    const hasSalesCol = r.length >= 6
    const sales30d = hasSalesCol ? Number(r[4]) || 0 : 0
    const timeRaw = hasSalesCol ? r[5] : r[4]
    const time = parseTsMsk(timeRaw)

    if (name && priceUsd > 0 && priceRub > 0) {
      rows.push({
        name,
        priceUsd,
        priceRub,
        sellListings,
        sales30d,
        time,
        timeMsk: formatTimeMskCell(timeRaw),
      })
    }
  }

  return { rows, meta }
}
