/**
 * @file Таблица профитных позиций на базе TanStack React Table.
 *
 * Колонки подстраиваются под выбранную пару маркетов.
 */

import {
  createColumnHelper,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getSortedRowModel,
  useReactTable,
  type SortingState,
} from '@tanstack/react-table'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { MARKETS, MARKET_BADGE, SALES_30D_SELL_MARKETS, type BuyMarketId, type MarketId } from '../lib/markets'
import { currencyCode, type DisplayCurrency } from '../lib/currency'
import { getOpportunityAmounts, type Opportunity } from '../types'

declare module '@tanstack/react-table' {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface ColumnMeta<TData, TValue> {
    separatorAfter?: boolean
  }
}

/** Сколько строк показываем изначально и подгружаем по кнопке. */
const PAGE_SIZE = 100

/** Хелпер для типизированных колонок TanStack Table. */
const columnHelper = createColumnHelper<Opportunity>()

/**
 * Форматирует число для отображения в ячейке (ru-RU).
 *
 * @param value — числовое значение.
 * @param digits — знаков после запятой.
 */
function numCell(value: number, digits = 2): string {
  return value.toLocaleString('ru-RU', {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  })
}

/**
 * CSS-класс строки/ячейки по знаку профита.
 *
 * @param pct — Profit %.
 */
function profitClass(pct: number): string {
  if (pct >= 10) return 'profit-high'
  if (pct >= 0) return 'profit-pos'
  return 'profit-neg'
}

/**
 * Ячейка Net sell: сумма и опционально % вычтенной комиссии (Steam / market.csgo).
 *
 * @param value — чистая выручка после комиссии.
 * @param feePct — эффективный % от цены покупателя; если задан — показывается как (−N%).
 */
function NetSellCell({ value, feePct }: { value: number; feePct?: number }) {
  return (
    <span className="net-sell-cell">
      <span>{numCell(value)}</span>
      {feePct != null && feePct > 0 && (
        <span className="net-sell-fee-pct" title="Комиссия от цены покупателя на маркете">
          {' '}
          (−{numCell(feePct, feePct >= 10 ? 0 : 1)}%)
        </span>
      )}
    </span>
  )
}

/** Копирует текст в буфер обмена (Clipboard API + fallback). */
async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    const textarea = document.createElement('textarea')
    textarea.value = text
    textarea.style.position = 'fixed'
    textarea.style.opacity = '0'
    document.body.appendChild(textarea)
    textarea.select()
    try {
      document.execCommand('copy')
      return true
    } catch {
      return false
    } finally {
      document.body.removeChild(textarea)
    }
  }
}

/** Название предмета с кнопкой копирования слева. */
function ItemNameCell({ name }: { name: string }) {
  const [copied, setCopied] = useState(false)

  const handleCopy = async (e: React.MouseEvent) => {
    e.stopPropagation()
    const ok = await copyText(name)
    if (!ok) return
    setCopied(true)
    window.setTimeout(() => setCopied(false), 1500)
  }

  return (
    <span className="item-name-cell">
      <button
        type="button"
        className={`item-name-copy-btn${copied ? ' item-name-copy-btn--copied' : ''}`}
        onClick={(e) => void handleCopy(e)}
        title={copied ? 'Скопировано' : 'Скопировать название'}
        aria-label={copied ? 'Скопировано' : 'Скопировать название'}
      >
        {copied ? (
          <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
            <path
              fill="currentColor"
              d="M9 16.17 4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"
            />
          </svg>
        ) : (
          <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
            <path
              fill="currentColor"
              d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"
            />
          </svg>
        )}
      </button>
      <span className="item-name" title={name}>
        {name}
      </span>
    </span>
  )
}

/** Закрывает предыдущий открытый buy-market тултип (в таблице сотни бейджей). */
let closeActiveBuyMarketTooltip: (() => void) | null = null

/** Метка маркета покупки с тултипом цен по всем источникам. */
function BuyMarketBadge({
  market,
  buyMarkets,
  prices,
  pricesUsd,
  currency,
}: {
  market: BuyMarketId
  buyMarkets: BuyMarketId[]
  prices?: Partial<Record<BuyMarketId, number>>
  pricesUsd?: Partial<Record<BuyMarketId, number>>
  currency: DisplayCurrency
}) {
  const badgeRef = useRef<HTMLSpanElement>(null)
  const [tooltipPos, setTooltipPos] = useState<{ top: number; left: number } | null>(
    null,
  )

  const hideTooltip = useCallback(() => {
    setTooltipPos(null)
  }, [])

  const hideAndUnregister = useCallback(() => {
    hideTooltip()
    if (closeActiveBuyMarketTooltip === hideAndUnregister) {
      closeActiveBuyMarketTooltip = null
    }
  }, [hideTooltip])

  const showTooltip = useCallback(() => {
    if (buyMarkets.length === 0) return
    const rect = badgeRef.current?.getBoundingClientRect()
    if (!rect) return
    closeActiveBuyMarketTooltip?.()
    closeActiveBuyMarketTooltip = hideAndUnregister
    setTooltipPos({
      top: rect.bottom + 6,
      left: rect.left,
    })
  }, [buyMarkets.length, hideAndUnregister])

  useEffect(() => {
    return () => {
      hideAndUnregister()
    }
  }, [hideAndUnregister])

  useEffect(() => {
    if (!tooltipPos) return

    const hideOnScrollOrResize = () => {
      hideAndUnregister()
    }

    window.addEventListener('scroll', hideOnScrollOrResize, true)
    window.addEventListener('resize', hideOnScrollOrResize)
    return () => {
      window.removeEventListener('scroll', hideOnScrollOrResize, true)
      window.removeEventListener('resize', hideOnScrollOrResize)
    }
  }, [hideAndUnregister, tooltipPos])

  return (
    <>
      <span
        ref={badgeRef}
        className="buy-market-badge-wrap"
        onMouseEnter={showTooltip}
        onMouseLeave={hideAndUnregister}
        onFocus={showTooltip}
        onBlur={hideAndUnregister}
      >
        <span
          className="buy-market-badge"
          tabIndex={0}
          aria-label={`Источник: ${MARKETS[market].label}`}
        >
          {MARKET_BADGE[market]}
        </span>
      </span>
      {tooltipPos &&
        buyMarkets.length > 0 &&
        createPortal(
          <span
            className="buy-market-tooltip buy-market-tooltip--fixed"
            style={{ top: tooltipPos.top, left: tooltipPos.left }}
            role="tooltip"
          >
            {buyMarkets.map((id) => {
              const price =
                currency === 'USD' ? pricesUsd?.[id] ?? prices?.[id] : prices?.[id]
              const isBest = id === market
              return (
                <span
                  key={id}
                  className={`buy-market-tooltip-row${isBest ? ' buy-market-tooltip-row--best' : ''}`}
                >
                  <span className="buy-market-tooltip-label">{MARKETS[id].label}</span>
                  <span className="buy-market-tooltip-price">
                    {price != null ? numCell(price) : '-'}
                  </span>
                </span>
              )
            })}
          </span>,
          document.body,
        )}
    </>
  )
}

/** Цена покупки с меткой маркета-источника. */
function BuyPriceCell({
  value,
  multiBuyMode,
  buyMarkets,
  opportunity,
  currency,
}: {
  value: number
  multiBuyMode: boolean
  buyMarkets: BuyMarketId[]
  opportunity: Opportunity
  currency: DisplayCurrency
}) {
  const market = opportunity.buyMarket
  if (!market) {
    return <span className="buy-price-value">{numCell(value)}</span>
  }

  return (
    <span className="buy-price-cell">
      <BuyMarketBadge
        market={market}
        buyMarkets={multiBuyMode ? buyMarkets : []}
        prices={multiBuyMode ? opportunity.buyMarketPrices : undefined}
        pricesUsd={multiBuyMode ? opportunity.buyMarketPricesUsd : undefined}
        currency={currency}
      />
      <span className="buy-price-value">{numCell(value)}</span>
    </span>
  )
}

/** Пропсы компонента {@link ProfitableTable}. */
interface ProfitableTableProps {
  /** Строки таблицы после расчёта профита. */
  data: Opportunity[]
  /** Маркеты покупки (источники). */
  buyMarkets: BuyMarketId[]
  /** Маркет продажи (сравнение). */
  sellMarket: MarketId | ''
  /** Сравнение всех buy-маркетов без выбора конкретного источника. */
  multiBuyMode?: boolean
  /** Валюта отображения цен и профита. */
  currency?: DisplayCurrency
  /** Идёт загрузка данных из Google Sheets. */
  loading?: boolean
  /** Пользователь уже нажимал «Искать». */
  searched?: boolean
  /** Текст ошибки загрузки (если была). */
  loadError?: string | null
}

/**
 * Интерактивная таблица сделок между двумя маркетами.
 *
 * @param props — {@link ProfitableTableProps}
 */
export function ProfitableTable({
  data,
  buyMarkets,
  sellMarket,
  multiBuyMode = false,
  currency = 'USD',
  loading = false,
  searched = false,
  loadError = null,
}: ProfitableTableProps) {
  const currencyLabel = currencyCode(currency)
  const marketsSelected = Boolean(sellMarket && buyMarkets.length > 0)
  const buyLabel = multiBuyMode
    ? 'Источник'
    : buyMarkets.length === 1
      ? MARKETS[buyMarkets[0]].shortLabel
      : 'Buy'
  const sellLabel = sellMarket ? MARKETS[sellMarket].shortLabel : 'Sell'
  const sellHasCommission = sellMarket === 'marketcsgo' || sellMarket === 'steam'
  const sellCommissionLabel =
    sellMarket === 'marketcsgo'
      ? '−5%'
      : sellMarket === 'steam'
        ? 'Steam fee'
        : undefined
  const showSales30d = Boolean(sellMarket && SALES_30D_SELL_MARKETS.includes(sellMarket))

  const [sorting, setSorting] = useState<SortingState>([
    { id: 'profitPct', desc: true },
  ])
  const [globalFilter, setGlobalFilter] = useState('')
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE)
  const [selectedRowId, setSelectedRowId] = useState<string | null>(null)

  useEffect(() => {
    setVisibleCount(PAGE_SIZE)
  }, [data, globalFilter, sorting])

  useEffect(() => {
    setSelectedRowId(null)
  }, [data])

  const columns = useMemo(
    () => [
      columnHelper.accessor('name', {
        header: 'Name skin',
        cell: (info) => <ItemNameCell name={info.getValue()} />,
        size: 280,
      }),
      columnHelper.display({
        id: 'buyPrice',
        header: `BUY ${currencyLabel}`,
        cell: (info) => {
          const amounts = getOpportunityAmounts(info.row.original, currency)
          return (
            <BuyPriceCell
              value={amounts.buy}
              multiBuyMode={multiBuyMode}
              buyMarkets={buyMarkets}
              opportunity={info.row.original}
              currency={currency}
            />
          )
        },
      }),
      columnHelper.accessor('buyDate', {
        header: 'BUY дата',
        cell: (info) => info.getValue(),
        meta: { separatorAfter: true },
      }),
      columnHelper.display({
        id: 'sellPrice',
        header: `${sellLabel} ${currencyLabel}`,
        cell: (info) => numCell(getOpportunityAmounts(info.row.original, currency).sell),
      }),
      ...(showSales30d
        ? [
            columnHelper.accessor('sales30d', {
              header: `Продаж/мес (${sellLabel})`,
              cell: (info) => info.getValue(),
            }),
          ]
        : []),
      columnHelper.accessor('sellVolume', {
        header: `В продаже (${sellLabel})`,
        cell: (info) => info.getValue(),
      }),
      columnHelper.accessor('sellDate', {
        header: `${sellLabel} дата (МСК)`,
        cell: (info) => info.getValue(),
      }),
      columnHelper.display({
        id: 'netSell',
        header: sellHasCommission
          ? sellCommissionLabel
            ? `Net sell ${currencyLabel} (${sellCommissionLabel})`
            : `Net sell ${currencyLabel}`
          : `Net sell ${currencyLabel}`,
        cell: (info) => {
          const amounts = getOpportunityAmounts(info.row.original, currency)
          return (
            <NetSellCell value={amounts.netSell} feePct={amounts.netSellFeePct} />
          )
        },
        meta: { separatorAfter: true },
      }),
      columnHelper.display({
        id: 'profit',
        header: `Profit ${currencyLabel}`,
        cell: (info) => (
          <span className={profitClass(info.row.original.profitPct)}>
            {numCell(getOpportunityAmounts(info.row.original, currency).profit)}
          </span>
        ),
      }),
      columnHelper.accessor('profitPct', {
        header: 'Profit %',
        cell: (info) => (
          <span className={profitClass(info.getValue())}>
            {numCell(info.getValue(), 1)}
          </span>
        ),
      }),
      columnHelper.accessor('buyUrl', {
        header: `${buyLabel} (open)`,
        enableSorting: false,
        cell: (info) => (
          <a href={info.getValue()} target="_blank" rel="noreferrer">
            open
          </a>
        ),
      }),
      columnHelper.accessor('sellUrl', {
        header: `${sellLabel} (open)`,
        enableSorting: false,
        cell: (info) => (
          <a href={info.getValue()} target="_blank" rel="noreferrer">
            open
          </a>
        ),
      }),
    ],
    [buyLabel, sellLabel, sellHasCommission, sellCommissionLabel, showSales30d, multiBuyMode, buyMarkets, currency, currencyLabel],
  )

  const table = useReactTable({
    data,
    columns,
    getRowId: (row) => `${row.name}\0${row.buyMarket ?? ''}`,
    state: { sorting, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    globalFilterFn: (row, _columnId, filterValue) => {
      const q = String(filterValue).toLowerCase()
      return row.original.name.toLowerCase().includes(q)
    },
  })

  const allRows = table.getRowModel().rows
  const visibleRows = allRows.slice(0, visibleCount)
  const hasMoreRows = visibleCount < allRows.length
  const remainingRows = allRows.length - visibleCount

  const colCount = table.getVisibleFlatColumns().length

  let emptyMessage = 'Выберите маркеты'
  if (marketsSelected && !searched) {
    emptyMessage = 'Нажмите «Искать»'
  } else if (marketsSelected && searched && loading) {
    emptyMessage = 'Читаем Google Sheets…'
  } else if (marketsSelected && searched && !loading && loadError) {
    emptyMessage = 'Ошибка загрузки — см. сообщение выше'
  } else if (marketsSelected && searched && !loading && data.length === 0) {
    emptyMessage = 'Нет позиций по выбранным фильтрам'
  }

  return (
    <div className="table-panel">
      <div className="table-toolbar">
        <input
          type="search"
          placeholder="Фильтр по названию…"
          value={globalFilter}
          onChange={(e) => setGlobalFilter(e.target.value)}
          disabled={!marketsSelected || !searched || loading}
        />
        <span className="row-count">
          {marketsSelected && searched && !loading && allRows.length > 0
            ? `Показано ${visibleRows.length} из ${allRows.length}`
            : marketsSelected && searched && !loading
              ? '0 строк'
              : ''}
        </span>
      </div>

      <div className="table-scroll">
        <table>
          <thead>
            {table.getHeaderGroups().map((hg) => (
              <tr key={hg.id}>
                {hg.headers.map((header) => (
                  <th
                    key={header.id}
                    onClick={header.column.getToggleSortingHandler()}
                    className={[
                      header.column.getCanSort() ? 'sortable' : '',
                      header.column.columnDef.meta?.separatorAfter
                        ? 'col-separator-after'
                        : '',
                    ]
                      .filter(Boolean)
                      .join(' ') || undefined}
                  >
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {{
                      asc: ' ▲',
                      desc: ' ▼',
                    }[header.column.getIsSorted() as string] ?? null}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {!marketsSelected || !searched || loading || data.length === 0 ? (
              <tr className="table-empty-row">
                <td colSpan={colCount} className="table-empty">
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              visibleRows.map((row) => (
                <tr
                  key={row.id}
                  className={row.id === selectedRowId ? 'table-row-selected' : undefined}
                  onClick={() => setSelectedRowId(row.id)}
                >
                  {row.getVisibleCells().map((cell) => (
                    <td
                      key={cell.id}
                      className={
                        cell.column.columnDef.meta?.separatorAfter
                          ? 'col-separator-after'
                          : undefined
                      }
                    >
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {hasMoreRows && (
        <button
          type="button"
          className="table-load-more-btn"
          onClick={() =>
            setVisibleCount((prev) => Math.min(prev + PAGE_SIZE, allRows.length))
          }
        >
          Подгрузить ещё {Math.min(PAGE_SIZE, remainingRows)}+ позиций
        </button>
      )}
    </div>
  )
}
