/**
 * @file Точка входа загрузки данных: Google Sheets → расчёт профита.
 *
 * Вызывается из {@link App} после выбора пары маркетов и по кнопке «Обновить».
 */

import { assertAppConfig } from '../config'
import type { MarketRow, ProfitReport, SheetMeta, SteamRow } from '../types'
import type { BuyMarketId, MarketId } from './markets'
import { computeMultiBuyProfit, computeProfit } from './profit'
import {
  type BuffLoadOptions,
  type BuyPriceRange,
  type MarketcsgoLoadOptions,
  loadBdBuff,
  loadBdCsfloat,
  loadBdLiskins,
  loadBdMarketcsgo,
  loadBdSih,
  loadBdSteam,
  loadBdWhitemarket,
} from './sheets'

/** Фильтры, отсекаемые в gviz до join на фронте. */
export interface OpportunityLoadFilters {
  /** Цена покупки на маркете-источнике в выбранной валюте. */
  buyPriceRange?: BuyPriceRange | null
  /** Мин. продаж/мес на маркете продажи (market.csgo — E, Buff — D). */
  minSales30d?: number | null
}

/**
 * Загружает данные маркета из публичной Google Sheets.
 *
 * @param market — id маркета.
 * @param filters — gviz-фильтры для buy- или sell-side.
 * @param role — роль маркета в паре.
 */
async function loadMarket(
  market: MarketId,
  filters: OpportunityLoadFilters,
  role: 'buy' | 'sell',
): Promise<{ rows: SteamRow[] | MarketRow[]; meta: SheetMeta }> {
  switch (market) {
    case 'steam':
      return loadBdSteam(role === 'buy' ? filters.buyPriceRange : undefined)
    case 'buff': {
      const opts: BuffLoadOptions = {}
      if (role === 'buy' && filters.buyPriceRange) {
        opts.buyPriceRange = filters.buyPriceRange
      }
      if (role === 'sell' && filters.minSales30d != null) {
        opts.minSales30d = filters.minSales30d
      }
      return loadBdBuff(opts)
    }
    case 'liskins':
      return loadBdLiskins(role === 'buy' ? filters.buyPriceRange : undefined)
    case 'whitemarket':
      return loadBdWhitemarket(role === 'buy' ? filters.buyPriceRange : undefined)
    case 'csfloat':
      return loadBdCsfloat(role === 'buy' ? filters.buyPriceRange : undefined)
    case 'sih':
      return loadBdSih(role === 'buy' ? filters.buyPriceRange : undefined)
    case 'marketcsgo': {
      const opts: MarketcsgoLoadOptions = {}
      if (role === 'buy' && filters.buyPriceRange) {
        opts.buyPriceRange = filters.buyPriceRange
      }
      if (role === 'sell' && filters.minSales30d != null) {
        opts.minSales30d = filters.minSales30d
      }
      return loadBdMarketcsgo(opts)
    }
  }
}

/**
 * Читает две вкладки БД и считает профитные позиции для пары маркетов.
 *
 * На Google (gviz `tq`) до join:
 * - buy-side: цена в ₽ (Steam/Buff → USD по `usd_rub`; Market → `price_rub`);
 * - sell-side market.csgo / Buff: `sales_30d >= min` (колонки E / D).
 *
 * @param buyMarket — откуда покупаем.
 * @param sellMarket — с чем сравниваем / куда продаём.
 * @param filters — фильтры загрузки.
 * @returns Полный отчёт для таблицы UI.
 * @throws {Error} Ошибки gviz или конфигурации.
 */
export async function loadOpportunities(
  buyMarket: MarketId,
  sellMarket: MarketId,
  filters: OpportunityLoadFilters = {},
): Promise<ProfitReport> {
  assertAppConfig()

  const buy = await loadMarket(buyMarket, filters, 'buy')
  const sell = await loadMarket(sellMarket, filters, 'sell')

  return computeProfit(
    buy.rows,
    sell.rows,
    buy.meta,
    sell.meta,
    buyMarket,
    sellMarket,
  )
}

/**
 * Загружает выбранные buy-маркеты и sell-маркет, выбирая лучший источник на каждую позицию.
 *
 * @param sellMarket — с чем сравниваем / куда продаём.
 * @param buyMarkets — источники для сравнения (минимум один).
 * @param filters — фильтры загрузки (цена покупки применяется к каждому buy-маркету).
 */
export async function loadMultiBuyOpportunities(
  sellMarket: MarketId,
  buyMarkets: BuyMarketId[],
  filters: OpportunityLoadFilters = {},
): Promise<ProfitReport> {
  assertAppConfig()

  if (buyMarkets.length === 0) {
    throw new Error('Выберите хотя бы один маркет покупки')
  }

  const [sell, ...buyResults] = await Promise.all([
    loadMarket(sellMarket, filters, 'sell'),
    ...buyMarkets.map((market) => loadMarket(market, filters, 'buy')),
  ])

  const buyByMarket = Object.fromEntries(
    buyMarkets.map((market, index) => [market, buyResults[index]]),
  ) as Record<BuyMarketId, { rows: SteamRow[] | MarketRow[]; meta: SheetMeta }>

  return computeMultiBuyProfit(buyByMarket, buyMarkets, sell.rows, sell.meta, sellMarket)
}
